n by A.value:AmazonOrderId,A.value:MarketplaceName,A.value:PostedDate,A.value:SellerOrderId,B.value:OrderItemId,B.value:SellerSKU order by _airbyte_emitted_at desc) rw from vahdam_db.maplemonk.casp_aus_new_listfinancialevents ,lateral flatten(input =>SHIPMENTEVENTLIST)A,lateral flatten(input =>A.value:ShipmentItemList)B,lateral flatten(input =>B.value:ItemTaxWithheldList)C,lateral flatten(input =>C.value:TaxesWithheld)D where lower(A.value:MarketplaceName)=\'amazon.com.au\') where rw=1) group by 1,2,3,4,5,6,7), Fee as (select AmazonOrderId, MarketplaceName, PostedDate, SellerOrderId, OrderItemId, SellerSKU, Currency, sum(ifnull(FBAPerUnitFulfillmentFee,0)) FBAPerUnitFulfillmentFee, sum(ifnull(Commission,0)) Commission, sum(ifnull(GiftWrapChargeback,0)) GiftWrapChargeback, sum(ifnull(ShippingChargeback,0)) ShippingChargeback, sum(ifnull(VariableClosingFee,0)) VariableClosingFee, sum(ifnull(FixedclosingFee,0)) FixedclosingFee from (select * from (select A.value:AmazonOrderId as AmazonOrderId, A.value:MarketplaceName as MarketplaceName, A.value:PostedDate as PostedDate, A.value:SellerOrderId as SellerOrderId, B.value:OrderItemId as OrderItemId, B.value:SellerSKU as SellerSKU, D.value:\"FeeAmount\":\"CurrencyCode\" as Currency, case when lower(D.value:FeeType)=\'fbaperunitfulfillmentfee\' then D.value:\"FeeAmount\":\"CurrencyAmount\" end as FBAPerUnitFulfillmentFee, case when lower(D.value:FeeType)=\'commission\' then D.value:\"FeeAmount\":\"CurrencyAmount\" end as Commission, case when lower(D.value:FeeType)=\'giftwrapchargeback\' then D.value:\"FeeAmount\":\"CurrencyAmount\" end as GiftWrapChargeback, case when lower(D.value:FeeType)=\'shippingchargeback\' then D.value:\"FeeAmount\":\"CurrencyAmount\" end as ShippingChargeback, case when lower(D.value:FeeType)=\'variableclosingfee\' then D.value:\"FeeAmount\":\"CurrencyAmount\" end as VariableClosingFee, case when lower(D.value:FeeType)=\'fixedclosingfee\' then D.value:\"FeeAmount\":\"CurrencyAmount\" end as Fixedclos